// --- HOW DATA LOOKS IN BOTH ---

// SQL (Rigid Tables connected by IDs)
const sqlUsersTable = [{ id: 1, name: "Alice" }];
const sqlPostsTable = [{ id: 99, user_id: 1, title: "My Post" }];
// To get Alice's posts, you must run a computationally heavy 'JOIN' query.

// NoSQL (Embedded Documents)
const noSqlDatabase = [
  {
    id: 1,
    name: "Alice",
    // The posts are stored directly inside the user!
    // No heavy joins required. Read performance is incredibly fast.
    posts: [{ id: 99, title: "My Post" }]
  }
];

console.log("SQL: Great for complex relationships. NoSQL: Great for fast reads and unstructured data.");
